('YPS-FAMMI', '58e5940c-b551-4821-9be1-ceeb7ac33985', '2026-07', '{"meta":{"responden_id":"58e5940c-b551-4821-9be1-ceeb7ac33985","nama_responden":"Gilang Nasution","peran_kerja":"Guru","unit":"SMP Fammi","jenjang":"SMP","jenis_kelamin":"Laki-laki","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"tempat yang aman, cuma kurang ruang mencoba\"","sub_hook":"Profil budaya Anda paling condong ke Aturan, dengan jarak terbesar ke harapan ada di Inovasi."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di SMP Fammi adalah Aturan (61,7 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Inovasi: Anda mengharapkan porsinya lebih besar sekitar 24,9 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":45.78,"harapan":61.86},{"tipe":"Inovasi","saat_ini":44.91,"harapan":69.77},{"tipe":"Orientasi","saat_ini":60.94,"harapan":50.51},{"tipe":"Aturan","saat_ini":61.74,"harapan":42.52}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":16.08},{"label":"Inovasi","arah":"naik","nilai_gap":24.86},{"label":"Orientasi","arah":"turun","nilai_gap":-10.43},{"label":"Aturan","arah":"turun","nilai_gap":-19.22}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 67 dari 100, kategori Tinggi. Kenyamanan Bekerja jadi sisi terkuat Anda (80), sementara Work-Life Balance paling perlu dijaga (50).","indeks":67,"kategori":"Tinggi","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":73.33,"kategori":"Tinggi"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":66.67,"kategori":"Tinggi"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":66.67,"kategori":"Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Kinerja/Performa paling kuat Anda rasakan (75), sedangkan Sinergi Tim paling rendah (50) dengan harapan 65.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"management","label":"Manajemen","nilai":65,"kategori":"Tinggi","harapan":65,"gap":0},{"kode":"sinergi","label":"Sinergi Tim","nilai":50,"kategori":"Sedang","harapan":65,"gap":15},{"kode":"fokus","label":"Fokus Strategis","nilai":55,"kategori":"Sedang","harapan":60,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":75,"kategori":"Sangat Tinggi","harapan":70,"gap":-5}]},"bagian_cermin":"\"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.\" \"Menghadapi keluhan orang tua murid sendirian tanpa panduan yang jelas.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.","hal_menguras_energi":"Menghadapi keluhan orang tua murid sendirian tanpa panduan yang jelas.","yang_ingin_disampaikan":"Mohon kejelasan soal jenjang karier dan penghargaan kerja.","yang_ingin_diubah":"Jam pulang dihormati, pekerjaan tidak lagi mengejar sampai rumah.","gambaran_lembaga":"tempat yang aman, cuma kurang ruang mencoba"},"rencana_aksi":[{"id":"58e5940c-b551-4821-9be1-ceeb7ac33985-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 24,9 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"58e5940c-b551-4821-9be1-ceeb7ac33985-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 50 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"58e5940c-b551-4821-9be1-ceeb7ac33985-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 80 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (50 dari 100), sementara Kenyamanan Bekerja sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 24,9 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (50 dari 100, harapan 65). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
