('YPS-FAMMI', '4af83aa1-3f28-4f2b-99b5-063c9bc403e5', '2026-07', '{"meta":{"responden_id":"4af83aa1-3f28-4f2b-99b5-063c9bc403e5","nama_responden":"Irfan Maulana","peran_kerja":"Guru","unit":"SMP Fammi","jenjang":"SMP","jenis_kelamin":"Laki-laki","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"tim yang kompak kalau sedang ada acara besar\"","sub_hook":"Profil budaya Anda paling condong ke Aturan, dengan jarak terbesar ke harapan ada di Aturan."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di SMP Fammi adalah Aturan (46,4 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Aturan: Anda mengharapkan porsinya lebih kecil sekitar 26,8 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":39.19,"harapan":48.88},{"tipe":"Inovasi","saat_ini":40.68,"harapan":61.32},{"tipe":"Orientasi","saat_ini":33.19,"harapan":36.74},{"tipe":"Aturan","saat_ini":46.41,"harapan":19.65}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":9.69},{"label":"Inovasi","arah":"naik","nilai_gap":20.64},{"label":"Orientasi","arah":"naik","nilai_gap":3.55},{"label":"Aturan","arah":"turun","nilai_gap":-26.76}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 47 dari 100, kategori Sedang. Kenyamanan Bekerja jadi sisi terkuat Anda (60), sementara Pengembangan Diri paling perlu dijaga (40).","indeks":47,"kategori":"Sedang","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":53.33,"kategori":"Sedang"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":60,"kategori":"Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":40,"kategori":"Rendah"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":40,"kategori":"Rendah"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":40,"kategori":"Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (60), sedangkan Sinergi Tim paling rendah (40) dengan harapan 50.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":60,"kategori":"Tinggi","harapan":45,"gap":-15},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":50,"kategori":"Sedang","harapan":55,"gap":5},{"kode":"management","label":"Manajemen","nilai":50,"kategori":"Sedang","harapan":45,"gap":-5},{"kode":"sinergi","label":"Sinergi Tim","nilai":40,"kategori":"Rendah","harapan":50,"gap":10},{"kode":"fokus","label":"Fokus Strategis","nilai":45,"kategori":"Sedang","harapan":55,"gap":10},{"kode":"performance","label":"Kinerja/Performa","nilai":50,"kategori":"Sedang","harapan":55,"gap":5}]},"bagian_cermin":"\"Murid-muridnya bikin capek jadi terbayar.\" \"Tugas tambahan yang menumpuk di orang yang sama terus.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu keterampilan apa yang ingin Anda kuasai tiga bulan ke depan, dan kapan waktunya Anda sisihkan?","jawaban_survey":{"betah":"Murid-muridnya bikin capek jadi terbayar.","hal_menguras_energi":"Tugas tambahan yang menumpuk di orang yang sama terus.","yang_ingin_disampaikan":"Semoga ide dari guru yang lebih muda juga diberi ruang untuk dicoba.","yang_ingin_diubah":"Pembagian tugas tambahan lebih merata antarguru.","gambaran_lembaga":"tim yang kompak kalau sedang ada acara besar"},"rencana_aksi":[{"id":"4af83aa1-3f28-4f2b-99b5-063c9bc403e5-aksi-1","judul":"Coba satu keputusan kecil tanpa menunggu prosedur baru.","alasan":"Aturan terasa lebih mengikat dari yang Anda butuhkan. Mengambil satu keputusan di wilayah Anda sendiri membuktikan ruang gerak itu sebenarnya ada. Selisihnya 26,8 poin.","terkait":"Aturan","jangka":"Minggu ini","ikon":"🚪"},{"id":"4af83aa1-3f28-4f2b-99b5-063c9bc403e5-aksi-2","judul":"Pilih satu keterampilan untuk didalami tiga bulan ini.","alasan":"Pengembangan Diri jadi sisi terendah Anda. Menetapkan satu fokus membuat waktu belajar yang sempit tetap membekas. Angkanya sekarang 40 dari 100.","terkait":"Pengembangan Diri","jangka":"3 bulan","ikon":"📚"},{"id":"4af83aa1-3f28-4f2b-99b5-063c9bc403e5-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 60 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Pengembangan Diri jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 60. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Pilih satu keterampilan, bukan banyak sekaligus","instruksi":"Tentukan satu hal untuk didalami tiga bulan ke depan:","contoh":["Satu metode mengajar tertentu.","Satu alat bantu ajar yang belum dikuasai.","Satu cara menilai yang lebih cepat."],"tujuan":"Fokus yang sempit lebih mungkin selesai daripada rencana besar tanpa waktu."},{"judul":"Sisihkan 30 menit belajar dalam sepekan","instruksi":"Blokir satu slot tetap di jadwal Anda:","contoh":["Hari dan jam yang sama tiap pekan.","Bahan yang sudah disiapkan sebelumnya.","Catatan singkat setelah selesai."],"tujuan":"Kesempatan belajar jarang datang sendiri, ia harus dijadwalkan."},{"judul":"Cari satu rekan sebagai teman belajar","instruksi":"Ajak satu orang yang minatnya dekat:","contoh":["Sepakati apa yang mau dipelajari bersama.","Tentukan kapan saling mengabari kemajuan.","Coba satu praktik di kelas masing-masing."],"tujuan":"Belajar berdua membuat komitmen lebih sulit ditinggalkan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Aturan terpaut 26,8 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Usulkan satu prosedur yang perlu disederhanakan","instruksi":"Pilih satu prosedur yang paling sering menghambat, lalu:","contoh":["Tuliskan langkah yang sebenarnya tidak perlu.","Perkirakan waktu yang bisa dihemat.","Sampaikan ke koordinator unit."],"tujuan":"Aturan yang dirapikan mengembalikan waktu ke pekerjaan utama."},{"judul":"Bantu perjelas satu alur kerja yang membingungkan","instruksi":"Bersama satu rekan, buat:","contoh":["Daftar langkah dari awal sampai selesai.","Nama orang yang bertanggung jawab tiap langkah.","Contoh berkas yang benar."],"tujuan":"Kebingungan berulang biasanya bukan soal orangnya, tapi alurnya yang tidak pernah dituliskan."},{"judul":"Sampaikan aturan yang sudah tidak relevan","instruksi":"Kalau ada aturan yang tidak lagi cocok:","contoh":["Ceritakan kapan terakhir itu berguna.","Jelaskan hambatannya sekarang.","Usulkan penggantinya, bukan cuma penghapusannya."],"tujuan":"Usulan yang membawa pengganti lebih mungkin dipertimbangkan."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (40 dari 100, harapan 50). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
('YPS-FAMMI', '14b11c9f-4fef-409d-8782-b116821ca78d', '2026-07', '{"meta":{"responden_id":"14b11c9f-4fef-409d-8782-b116821ca78d","nama_responden":"Tania Pranata","peran_kerja":"Guru","unit":"SMP Fammi","jenjang":"SMP","jenis_kelamin":"Perempuan","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"ruang belajar bersama, bukan cuma tempat mengajar\"","sub_hook":"Profil budaya Anda paling condong ke Aturan, dengan jarak terbesar ke harapan ada di Inovasi."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di SMP Fammi adalah Aturan (50,3 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Inovasi: Anda mengharapkan porsinya lebih besar sekitar 29,1 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":39.19,"harapan":42.48},{"tipe":"Inovasi","saat_ini":48.88,"harapan":77.98},{"tipe":"Orientasi","saat_ini":40.08,"harapan":50.51},{"tipe":"Aturan","saat_ini":50.3,"harapan":38.86}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":3.29},{"label":"Inovasi","arah":"naik","nilai_gap":29.1},{"label":"Orientasi","arah":"naik","nilai_gap":10.43},{"label":"Aturan","arah":"turun","nilai_gap":-11.44}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 56 dari 100, kategori Sedang. Kenyamanan Bekerja jadi sisi terkuat Anda (70), sementara Work-Life Balance paling perlu dijaga (50).","indeks":56,"kategori":"Sedang","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":53.33,"kategori":"Sedang"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":70,"kategori":"Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":53.33,"kategori":"Sedang"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":53.33,"kategori":"Sedang"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (60), sedangkan Kepemimpinan paling rendah (40) dengan harapan 55.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":60,"kategori":"Tinggi","harapan":55,"gap":-5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":40,"kategori":"Rendah","harapan":55,"gap":15},{"kode":"management","label":"Manajemen","nilai":55,"kategori":"Sedang","harapan":60,"gap":5},{"kode":"sinergi","label":"Sinergi Tim","nilai":55,"kategori":"Sedang","harapan":65,"gap":10},{"kode":"fokus","label":"Fokus Strategis","nilai":55,"kategori":"Sedang","harapan":65,"gap":10},{"kode":"performance","label":"Kinerja/Performa","nilai":55,"kategori":"Sedang","harapan":60,"gap":5}]},"bagian_cermin":"\"Jarak dari rumah dekat dan jam kerjanya jelas.\" \"Pekerjaan yang terbawa sampai rumah hampir setiap malam.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Jarak dari rumah dekat dan jam kerjanya jelas.","hal_menguras_energi":"Pekerjaan yang terbawa sampai rumah hampir setiap malam.","yang_ingin_disampaikan":"Semoga ide dari guru yang lebih muda juga diberi ruang untuk dicoba.","yang_ingin_diubah":"Evaluasi program dijalankan rutin, bukan cuma saat ada masalah.","gambaran_lembaga":"ruang belajar bersama, bukan cuma tempat mengajar"},"rencana_aksi":[{"id":"14b11c9f-4fef-409d-8782-b116821ca78d-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 29,1 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"14b11c9f-4fef-409d-8782-b116821ca78d-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 50 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"14b11c9f-4fef-409d-8782-b116821ca78d-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 70 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (50 dari 100), sementara Kenyamanan Bekerja sudah kuat di 70. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 29,1 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Kepemimpinan jadi dimensi profil organisasi terendah menurut Anda (40 dari 100, harapan 55). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Bawa pola berulang ke jalur resmi","instruksi":"Lewat rapat atau laporan rutin, sampaikan:","contoh":["Pola keputusan yang sering terlambat.","Dampaknya pada kesiapan mengajar.","Usulan jalur konfirmasi yang lebih awal."],"tujuan":"Pola yang tercatat bisa jadi bahan kebijakan, keluhan sesaat tidak."},{"judul":"Usulkan jadwal bicara rutin dengan pimpinan","instruksi":"Ajukan usulan sederhana:","contoh":["Waktu singkat berkala per unit.","Agenda dibuka dari staf, bukan dari pimpinan.","Catatan hasil yang bisa ditagih."],"tujuan":"Percakapan yang terjadwal menutup jarak lebih cepat daripada menunggu momen."},{"judul":"Minta alasan di balik keputusan besar","instruksi":"Saat ada kebijakan baru, tanyakan:","contoh":["Apa yang mendasari keputusan itu.","Pilihan apa saja yang sempat dipertimbangkan.","Bagaimana keberhasilannya akan dinilai."],"tujuan":"Kebiasaan bertanya membentuk kebiasaan menjelaskan."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
