fe_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (75), sedangkan Kepemimpinan paling rendah (45) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":75,"kategori":"Sangat Tinggi","harapan":70,"gap":-5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":45,"kategori":"Sedang","harapan":60,"gap":15},{"kode":"management","label":"Manajemen","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5},{"kode":"sinergi","label":"Sinergi Tim","nilai":50,"kategori":"Sedang","harapan":60,"gap":10},{"kode":"fokus","label":"Fokus Strategis","nilai":55,"kategori":"Sedang","harapan":65,"gap":10},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":55,"gap":-10}]},"bagian_cermin":"\"Sekolah memberi kepercayaan untuk mengelola kelas dengan cara sendiri.\" \"Laporan administrasi yang formatnya berubah-ubah menjelang tenggat.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Sekolah memberi kepercayaan untuk mengelola kelas dengan cara sendiri.","hal_menguras_energi":"Laporan administrasi yang formatnya berubah-ubah menjelang tenggat.","yang_ingin_disampaikan":"Kalau bisa pelatihan dibuka untuk semua guru, bukan bergiliran orang yang sama.","yang_ingin_diubah":"Jam pulang dihormati, pekerjaan tidak lagi mengejar sampai rumah.","gambaran_lembaga":"keluarga besar yang saling menutupi kekurangan"},"rencana_aksi":[{"id":"a4df21b9-b1ad-4aba-b72f-e4a112197d92-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara 