ance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (70), sedangkan Kepemimpinan paling rendah (50) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":55,"gap":-15},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":50,"kategori":"Sedang","harapan":60,"gap":10},{"kode":"management","label":"Manajemen","nilai":65,"kategori":"Tinggi","harapan":65,"gap":0},{"kode":"sinergi","label":"Sinergi Tim","nilai":55,"kategori":"Sedang","harapan":55,"gap":0},{"kode":"fokus","label":"Fokus Strategis","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":55,"gap":-10}]},"bagian_cermin":"\"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.\" \"Koreksi pekerjaan murid yang menumpuk sampai akhir pekan.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.","hal_menguras_energi":"Koreksi pekerjaan murid yang menumpuk sampai akhir pekan.","yang_ingin_disampaikan":"Beban administrasi tolong ditinjau ulang supaya waktu mengajar tidak terpotong.","yang_ingin_diubah":"Beban administrasi guru dikurangi atau dibantu tenaga khusus.","gambaran_lembaga":"keluarga besar yang saling menutupi kekurangan"},"rencana_aksi":[{"id":"0654811d-957b-4945-a794-d673055a20df-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 20,6 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"0654811d-957b-4945-a794-d673055a20df-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 50 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"0654811d-957b-4945-a794-d673055a20df-aksi-3","judul":"Bagikan satu hal yang baru Anda pelajari ke rekan.","alasan":"Pengembangan Diri jadi sisi terkuat Anda. Membagikannya membuat yang Anda pelajari mengendap lebih dalam. Angkanya 73,3 dari 100.","terkait":"Pengembangan Diri","jangka":"3 bulan","ikon":"🎓"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (50 dari 100), sementara Pengembangan Diri sudah kuat di 73,3. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 20,6 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Kepemimpinan jadi dimensi profil organisasi terendah menurut Anda (50 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Bawa pola berulang ke jalur resmi","instruksi":"Lewat rapat atau laporan rutin, sampaikan:","contoh":["Pola keputusan yang sering terlambat.","Dampaknya pada kesiapan mengajar.","Usulan jalur konfirmasi yang lebih awal."],"tujuan":"Pola yang tercatat bisa jadi bahan kebijakan, keluhan sesaat tidak."},{"judul":"Usulkan jadwal bicara rutin dengan pimpinan","instruksi":"Ajukan usulan sederhana:","contoh":["Waktu singkat berkala per unit.","Agenda dibuka dari staf, bukan dari pimpinan.","Catatan hasil yang bisa ditagih."],"tujuan":"Percakapan yang terjadwal menutup jarak lebih cepat daripada menunggu momen."},{"judul":"Minta alasan di balik keputusan besar","instruksi":"Saat ada kebijakan baru, tanyakan:","contoh":["Apa yang mendasari keputusan itu.","Pilihan apa saja yang sempat dipertimbangkan.","Bagaimana keberhasilannya akan dinilai."],"tujuan":"Kebiasaan bertanya membentuk kebiasaan menjelaskan."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
