ce","label":"Work-Life Balance","nilai":40,"kategori":"Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Fokus Strategis paling kuat Anda rasakan (60), sedangkan Sinergi Tim paling rendah (40) dengan harapan 45.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":50,"kategori":"Sedang","harapan":60,"gap":10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":45,"kategori":"Sedang","harapan":65,"gap":20},{"kode":"management","label":"Manajemen","nilai":45,"kategori":"Sedang","harapan":55,"gap":10},{"kode":"sinergi","label":"Sinergi Tim","nilai":40,"kategori":"Rendah","harapan":45,"gap":5},{"kode":"fokus","label":"Fokus Strategis","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":50,"kategori":"Sedang","harapan":65,"gap":15}]},"bagian_cermin":"\"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.\" \"Pekerjaan yang terbawa sampai rumah hampir setiap malam.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SMP Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.","hal_menguras_energi":"Pekerjaan yang terbawa sampai rumah hampir setiap malam.","yang_ingin_disampaikan":"Semoga ide dari guru yang lebih muda juga diberi ruang untuk dicoba.","yang_ingin_diubah":"Beban administrasi guru dikurangi atau dibantu tenaga khusus.","gambaran_lembaga":"tempat yang aman, cuma kurang ruang mencoba"},"rencana_aksi":[{"id":"25517ba3-dc42-40f3-97b9-a028f410fef0-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 37,3 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"25517ba3-dc42-40f3-97b9-a028f410fef0-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 40 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"25517ba3-dc42-40f3-97b9-a028f410fef0-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 60 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 60. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 37,3 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (40 dari 100, harapan 45). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
