ance","nilai":40,"kategori":"Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (70), sedangkan Manajemen paling rendah (45) dengan harapan 55.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":60,"gap":-10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":50,"kategori":"Sedang","harapan":70,"gap":20},{"kode":"management","label":"Manajemen","nilai":45,"kategori":"Sedang","harapan":55,"gap":10},{"kode":"sinergi","label":"Sinergi Tim","nilai":45,"kategori":"Sedang","harapan":50,"gap":5},{"kode":"fokus","label":"Fokus Strategis","nilai":55,"kategori":"Sedang","harapan":60,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":55,"kategori":"Sedang","harapan":70,"gap":15}]},"bagian_cermin":"\"Sesama guru saling menutup kalau ada yang berhalangan hadir.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di SMA Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu keterampilan apa yang ingin Anda kuasai tiga bulan ke depan, dan kapan waktunya Anda sisihkan?","jawaban_survey":{"betah":"Sesama guru saling menutup kalau ada yang berhalangan hadir.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Kalau bisa pelatihan dibuka untuk semua guru, bukan bergiliran orang yang sama.","yang_ingin_diubah":"Pelatihan dibuka untuk semua, bukan bergiliran orang yang sama.","gambaran_lembaga":"sekolah yang rapi dan serba terjadwal"},"rencana_aksi":[{"id":"97ac9724-dc9c-4056-b3d3-5628c5763fa4-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 45,8 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"97ac9724-dc9c-4056-b3d3-5628c5763fa4-aksi-2","judul":"Pilih satu keterampilan untuk didalami tiga bulan ini.","alasan":"Pengembangan Diri jadi sisi terendah Anda. Menetapkan satu fokus membuat waktu belajar yang sempit tetap membekas. Angkanya sekarang 40 dari 100.","terkait":"Pengembangan Diri","jangka":"3 bulan","ikon":"📚"},{"id":"97ac9724-dc9c-4056-b3d3-5628c5763fa4-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 80 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Pengembangan Diri jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Pilih satu keterampilan, bukan banyak sekaligus","instruksi":"Tentukan satu hal untuk didalami tiga bulan ke depan:","contoh":["Satu metode mengajar tertentu.","Satu alat bantu ajar yang belum dikuasai.","Satu cara menilai yang lebih cepat."],"tujuan":"Fokus yang sempit lebih mungkin selesai daripada rencana besar tanpa waktu."},{"judul":"Sisihkan 30 menit belajar dalam sepekan","instruksi":"Blokir satu slot tetap di jadwal Anda:","contoh":["Hari dan jam yang sama tiap pekan.","Bahan yang sudah disiapkan sebelumnya.","Catatan singkat setelah selesai."],"tujuan":"Kesempatan belajar jarang datang sendiri, ia harus dijadwalkan."},{"judul":"Cari satu rekan sebagai teman belajar","instruksi":"Ajak satu orang yang minatnya dekat:","contoh":["Sepakati apa yang mau dipelajari bersama.","Tentukan kapan saling mengabari kemajuan.","Coba satu praktik di kelas masing-masing."],"tujuan":"Belajar berdua membuat komitmen lebih sulit ditinggalkan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 45,8 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Manajemen jadi dimensi profil organisasi terendah menurut Anda (45 dari 100, harapan 55). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan penyederhanaan satu laporan","instruksi":"Pilih laporan yang paling memakan waktu, lalu:","contoh":["Tandai bagian yang datanya sudah ada di tempat lain.","Hitung waktu yang habis tiap bulan.","Sampaikan ke bagian yang memintanya."],"tujuan":"Waktu administrasi yang kembali langsung terasa di jam mengajar."},{"judul":"Bantu bakukan satu alur yang sering berubah","instruksi":"Bersama unit Anda, sepakati:","contoh":["Format yang dipakai seterusnya.","Tenggat yang realistis.","Siapa yang menjawab kalau ada pertanyaan."],"tujuan":"Format yang stabil menghilangkan pekerjaan ulang yang tidak perlu."},{"judul":"Ajukan kalender kegiatan satu semester","instruksi":"Usulkan ke pimpinan:","contoh":["Kegiatan tetap yang sudah pasti.","Batas waktu penambahan kegiatan baru.","Cara mengumumkan perubahan."],"tujuan":"Kepastian jadwal adalah keluhan yang paling sering muncul dan paling mudah diperbaiki."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
