('YPS-FAMMI', '881163bd-c36b-4ef3-ba97-ea4974b4bf12', '2026-07', '{"meta":{"responden_id":"881163bd-c36b-4ef3-ba97-ea4974b4bf12","nama_responden":"Nadia Kurniawan","peran_kerja":"Guru","unit":"SMA Fammi","jenjang":"SMA","jenis_kelamin":"Perempuan","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"tempat yang tertib tapi agak kaku\"","sub_hook":"Profil budaya Anda paling condong ke Kekeluargaan, dengan jarak terbesar ke harapan ada di Inovasi."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di SMA Fammi adalah Kekeluargaan (48,9 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Inovasi: Anda mengharapkan porsinya lebih besar sekitar 33,1 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":48.88,"harapan":61.86},{"tipe":"Inovasi","saat_ini":53.11,"harapan":86.18},{"tipe":"Orientasi","saat_ini":54.06,"harapan":57.61},{"tipe":"Aturan","saat_ini":53.96,"harapan":38.86}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":12.98},{"label":"Inovasi","arah":"naik","nilai_gap":33.07},{"label":"Orientasi","arah":"naik","nilai_gap":3.55},{"label":"Aturan","arah":"turun","nilai_gap":-15.1}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 53 dari 100, kategori Sedang. Kenyamanan Bekerja jadi sisi terkuat Anda (70), sementara Kepuasan pada Kepemimpinan paling perlu dijaga (46,7).","indeks":53,"kategori":"Sedang","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":46.67,"kategori":"Sedang"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":70,"kategori":"Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":46.67,"kategori":"Sedang"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":53.33,"kategori":"Sedang"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (65), sedangkan Sinergi Tim paling rendah (45) dengan harapan 50.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":65,"kategori":"Tinggi","harapan":75,"gap":10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":80,"gap":20},{"kode":"management","label":"Manajemen","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5},{"kode":"sinergi","label":"Sinergi Tim","nilai":45,"kategori":"Sedang","harapan":50,"gap":5},{"kode":"fokus","label":"Fokus Strategis","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":65,"gap":0}]},"bagian_cermin":"\"Jarak dari rumah dekat dan jam kerjanya jelas.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SMA Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu hal apa yang ingin Anda tanyakan langsung ke pimpinan unit bulan ini, yang selama ini cuma Anda simpan sendiri?","jawaban_survey":{"betah":"Jarak dari rumah dekat dan jam kerjanya jelas.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Kalau bisa pelatihan dibuka untuk semua guru, bukan bergiliran orang yang sama.","yang_ingin_diubah":"Keputusan penting dijelaskan alasannya, bukan cuma diumumkan.","gambaran_lembaga":"tempat yang tertib tapi agak kaku"},"rencana_aksi":[{"id":"881163bd-c36b-4ef3-ba97-ea4974b4bf12-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 33,1 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"881163bd-c36b-4ef3-ba97-ea4974b4bf12-aksi-2","judul":"Bawa satu masalah nyata ke pimpinan unit.","alasan":"Kepuasan pada Kepemimpinan jadi sisi terendah Anda. Menyampaikan satu masalah konkret dengan usulan solusinya membuka percakapan yang selama ini tertunda. Angkanya sekarang 46,7 dari 100.","terkait":"Kepuasan pada Kepemimpinan","jangka":"Bulan ini","ikon":"🗣️"},{"id":"881163bd-c36b-4ef3-ba97-ea4974b4bf12-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 70 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Kepuasan pada Kepemimpinan jadi sisi kesejahteraan terendah Anda (46,7 dari 100), sementara Kenyamanan Bekerja sudah kuat di 70. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Catat pola masalah sebelum menyampaikannya","instruksi":"Selama dua minggu, catat setiap kali:","contoh":["Keputusan yang tidak jelas dasarnya.","Informasi yang datang terlambat.","Dampaknya pada pekerjaan Anda hari itu."],"tujuan":"Supaya yang Anda sampaikan berupa pola, bukan kesan sesaat."},{"judul":"Siapkan satu usulan, bukan cuma keluhan","instruksi":"Untuk satu masalah yang paling sering muncul, tuliskan:","contoh":["Apa yang terjadi sekarang.","Apa yang Anda usulkan.","Apa yang Anda siap kerjakan sendiri."],"tujuan":"Percakapan dengan pimpinan berjalan lebih jauh kalau ada usulan konkret di dalamnya."},{"judul":"Pilih waktu bicara yang bukan saat genting","instruksi":"Cari satu momen tenang untuk bicara, misalnya:","contoh":["Setelah jam mengajar terakhir.","Di luar minggu ujian.","Bukan lewat pesan singkat."],"tujuan":"Isi pembicaraan lebih terdengar kalau waktunya tepat."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 33,1 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (45 dari 100, harapan 50). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
