nce","label":"Work-Life Balance","nilai":40,"kategori":"Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (75), sedangkan Fokus Strategis paling rendah (50) dengan harapan 70.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":75,"kategori":"Sangat Tinggi","harapan":65,"gap":-10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":65,"kategori":"Tinggi","harapan":70,"gap":5},{"kode":"management","label":"Manajemen","nilai":75,"kategori":"Sangat Tinggi","harapan":60,"gap":-15},{"kode":"sinergi","label":"Sinergi Tim","nilai":55,"kategori":"Sedang","harapan":55,"gap":0},{"kode":"fokus","label":"Fokus Strategis","nilai":50,"kategori":"Sedang","harapan":70,"gap":20},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5}]},"bagian_cermin":"\"Sekolah memberi kepercayaan untuk mengelola kelas dengan cara sendiri.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Orientasi jadi sisi budaya yang paling terasa di SMK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Sekolah memberi kepercayaan untuk mengelola kelas dengan cara sendiri.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Komunikasi antarunit perlu diperkuat supaya tidak jalan sendiri-sendiri.","yang_ingin_diubah":"Ada waktu khusus untuk mencoba metode mengajar baru.","gambaran_lembaga":"tempat belajar yang ramai tapi menyenangkan"},"rencana_aksi":[{"id":"b517a665-fbb0-49cb-8e92-df95bf0fdb52-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 20,6 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"b517a665-fbb0-49cb-8e92-df95bf0fdb52-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 40 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"b517a665-fbb0-49cb-8e92-df95bf0fdb52-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 80 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 20,6 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Fokus Strategis jadi dimensi profil organisasi terendah menurut Anda (50 dari 100, harapan 70). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Minta prioritas program dijelaskan ulang","instruksi":"Di forum resmi, tanyakan:","contoh":["Program mana yang paling utama semester ini.","Program mana yang bisa ditunda.","Ukuran keberhasilan tiap program."],"tujuan":"Fokus yang tidak dinyatakan membuat semua program terasa sama pentingnya."},{"judul":"Usulkan penghentian satu kegiatan yang tumpang tindih","instruksi":"Sampaikan dengan data sederhana:","contoh":["Kegiatan yang tujuannya sama dengan kegiatan lain.","Waktu dan tenaga yang terpakai.","Usulan penggabungannya."],"tujuan":"Fokus bertambah dari yang dihentikan, bukan dari yang ditambahkan."},{"judul":"Kaitkan pekerjaan unit dengan tujuan lembaga","instruksi":"Di rapat unit, coba:","contoh":["Sebutkan tujuan lembaga yang sedang dikejar.","Tunjukkan bagian yang dikerjakan unit Anda.","Tandai yang tidak terhubung ke mana-mana."],"tujuan":"Pekerjaan yang jelas kaitannya lebih mudah dipertahankan saat jadwal padat."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
