('YPS-FAMMI', 'bdb82386-1eb4-4801-a6c6-ebb571dcf544', '2026-07', '{"meta":{"responden_id":"bdb82386-1eb4-4801-a6c6-ebb571dcf544","nama_responden":"Sinta Puspita","peran_kerja":"Pimpinan Unit","unit":"SMK Fammi","jenjang":"SMK","jenis_kelamin":"Perempuan","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"mesin yang jalan rapi tapi jarang dievaluasi\"","sub_hook":"Profil budaya Anda paling condong ke Kekeluargaan, dengan jarak terbesar ke harapan ada di Kekeluargaan."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di SMK Fammi adalah Kekeluargaan (36,1 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Kekeluargaan: Anda mengharapkan porsinya lebih besar sekitar 12,8 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":36.09,"harapan":48.88},{"tipe":"Inovasi","saat_ini":48.88,"harapan":61.32},{"tipe":"Orientasi","saat_ini":43.62,"harapan":50.51},{"tipe":"Aturan","saat_ini":27.43,"harapan":27.43}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":12.79},{"label":"Inovasi","arah":"naik","nilai_gap":12.44},{"label":"Orientasi","arah":"naik","nilai_gap":6.89},{"label":"Aturan","arah":"tetap","nilai_gap":0}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 52 dari 100, kategori Sedang. Kenyamanan Bekerja jadi sisi terkuat Anda (70), sementara Pengembangan Diri paling perlu dijaga (40).","indeks":52,"kategori":"Sedang","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":60,"kategori":"Tinggi"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":70,"kategori":"Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":40,"kategori":"Rendah"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":40,"kategori":"Rendah"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Karakter Lembaga paling kuat Anda rasakan (60), sedangkan Fokus Strategis paling rendah (40) dengan harapan 65.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":55,"kategori":"Sedang","harapan":60,"gap":5},{"kode":"management","label":"Manajemen","nilai":50,"kategori":"Sedang","harapan":55,"gap":5},{"kode":"sinergi","label":"Sinergi Tim","nilai":45,"kategori":"Sedang","harapan":50,"gap":5},{"kode":"fokus","label":"Fokus Strategis","nilai":40,"kategori":"Rendah","harapan":65,"gap":25},{"kode":"performance","label":"Kinerja/Performa","nilai":40,"kategori":"Rendah","harapan":45,"gap":5}]},"bagian_cermin":"\"Jarak dari rumah dekat dan jam kerjanya jelas.\" \"Rapat panjang yang berakhir tanpa keputusan.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di SMK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu keterampilan apa yang ingin Anda kuasai tiga bulan ke depan, dan kapan waktunya Anda sisihkan?","jawaban_survey":{"betah":"Jarak dari rumah dekat dan jam kerjanya jelas.","hal_menguras_energi":"Rapat panjang yang berakhir tanpa keputusan.","yang_ingin_disampaikan":"Mohon kejelasan soal jenjang karier dan penghargaan kerja.","yang_ingin_diubah":"Pelatihan dibuka untuk semua, bukan bergiliran orang yang sama.","gambaran_lembaga":"mesin yang jalan rapi tapi jarang dievaluasi"},"rencana_aksi":[{"id":"bdb82386-1eb4-4801-a6c6-ebb571dcf544-aksi-1","judul":"Sisihkan satu jam untuk menemani rekan satu unit.","alasan":"Harapan Anda pada kedekatan antarrekan lebih tinggi dari yang Anda rasakan sekarang. Kedekatan tumbuh dari pertemuan yang disengaja, bukan dari kebetulan berpapasan di koridor. Selisihnya 12,8 poin.","terkait":"Kekeluargaan","jangka":"Bulan ini","ikon":"🤝"},{"id":"bdb82386-1eb4-4801-a6c6-ebb571dcf544-aksi-2","judul":"Pilih satu keterampilan untuk didalami tiga bulan ini.","alasan":"Pengembangan Diri jadi sisi terendah Anda. Menetapkan satu fokus membuat waktu belajar yang sempit tetap membekas. Angkanya sekarang 40 dari 100.","terkait":"Pengembangan Diri","jangka":"3 bulan","ikon":"📚"},{"id":"bdb82386-1eb4-4801-a6c6-ebb571dcf544-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 70 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Pengembangan Diri jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 70. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Pilih satu keterampilan, bukan banyak sekaligus","instruksi":"Tentukan satu hal untuk didalami tiga bulan ke depan:","contoh":["Satu metode mengajar tertentu.","Satu alat bantu ajar yang belum dikuasai.","Satu cara menilai yang lebih cepat."],"tujuan":"Fokus yang sempit lebih mungkin selesai daripada rencana besar tanpa waktu."},{"judul":"Sisihkan 30 menit belajar dalam sepekan","instruksi":"Blokir satu slot tetap di jadwal Anda:","contoh":["Hari dan jam yang sama tiap pekan.","Bahan yang sudah disiapkan sebelumnya.","Catatan singkat setelah selesai."],"tujuan":"Kesempatan belajar jarang datang sendiri, ia harus dijadwalkan."},{"judul":"Cari satu rekan sebagai teman belajar","instruksi":"Ajak satu orang yang minatnya dekat:","contoh":["Sepakati apa yang mau dipelajari bersama.","Tentukan kapan saling mengabari kemajuan.","Coba satu praktik di kelas masing-masing."],"tujuan":"Belajar berdua membuat komitmen lebih sulit ditinggalkan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Kekeluargaan terpaut 12,8 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Mulai satu kebiasaan menyapa di unit","instruksi":"Di pekan berikutnya, coba:","contoh":["Sapa rekan yang jarang Anda ajak bicara.","Tanyakan kabar pekerjaannya, bukan cuma agendanya.","Lakukan berulang, bukan sekali."],"tujuan":"Kedekatan tumbuh dari kebiasaan kecil yang diulang, bukan dari acara besar."},{"judul":"Usulkan satu momen kumpul tanpa agenda kerja","instruksi":"Sampaikan ke koordinator unit:","contoh":["Waktu singkat setelah rapat rutin.","Tanpa materi dan tanpa laporan.","Bergantian yang menyiapkan."],"tujuan":"Ruang bicara di luar agenda kerja membuat masalah kecil ketahuan lebih awal."},{"judul":"Temani satu rekan yang sedang kewalahan","instruksi":"Kalau ada rekan yang jelas kelebihan beban:","contoh":["Tawarkan bantuan yang spesifik, bukan basa-basi.","Ambil satu bagian pekerjaannya.","Ceritakan ke koordinator kalau polanya berulang."],"tujuan":"Kekeluargaan terasa nyata saat beban benar-benar berpindah, bukan cuma disimpati."}]},{"locus":"system","mengapa_fokus":"Fokus Strategis jadi dimensi profil organisasi terendah menurut Anda (40 dari 100, harapan 65). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Minta prioritas program dijelaskan ulang","instruksi":"Di forum resmi, tanyakan:","contoh":["Program mana yang paling utama semester ini.","Program mana yang bisa ditunda.","Ukuran keberhasilan tiap program."],"tujuan":"Fokus yang tidak dinyatakan membuat semua program terasa sama pentingnya."},{"judul":"Usulkan penghentian satu kegiatan yang tumpang tindih","instruksi":"Sampaikan dengan data sederhana:","contoh":["Kegiatan yang tujuannya sama dengan kegiatan lain.","Waktu dan tenaga yang terpakai.","Usulan penggabungannya."],"tujuan":"Fokus bertambah dari yang dihentikan, bukan dari yang ditambahkan."},{"judul":"Kaitkan pekerjaan unit dengan tujuan lembaga","instruksi":"Di rapat unit, coba:","contoh":["Sebutkan tujuan lembaga yang sedang dikejar.","Tunjukkan bagian yang dikerjakan unit Anda.","Tandai yang tidak terhubung ke mana-mana."],"tujuan":"Pekerjaan yang jelas kaitannya lebih mudah dipertahankan saat jadwal padat."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
