el":"Work-Life Balance","nilai":40,"kategori":"Rendah"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Fokus Strategis paling kuat Anda rasakan (65), sedangkan Manajemen paling rendah (35) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":60,"kategori":"Tinggi","harapan":50,"gap":-10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":40,"kategori":"Rendah","harapan":60,"gap":20},{"kode":"management","label":"Manajemen","nilai":35,"kategori":"Rendah","harapan":60,"gap":25},{"kode":"sinergi","label":"Sinergi Tim","nilai":50,"kategori":"Sedang","harapan":60,"gap":10},{"kode":"fokus","label":"Fokus Strategis","nilai":65,"kategori":"Tinggi","harapan":65,"gap":0},{"kode":"performance","label":"Kinerja/Performa","nilai":55,"kategori":"Sedang","harapan":50,"gap":-5}]},"bagian_cermin":"\"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Orientasi jadi sisi budaya yang paling terasa di SMK Fammi, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Suasana kerjanya hangat, tidak ada yang dibiarkan sendirian waktu kewalahan.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Saya berharap keputusan sekolah dijelaskan alasannya ke semua staf.","yang_ingin_diubah":"Ada kejelasan jenjang karier untuk guru dan tenaga kependidikan.","gambaran_lembaga":"kapal yang jalan terus tanpa sempat berhenti"},"rencana_aksi":[{"id":"4dc6e75d-0f87-4a94-bab2-4b07521ddf5a-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 16,7 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"4dc6e75d-0f87-4a94-bab2-4b07521ddf5a-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 40 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"4dc6e75d-0f87-4a94-bab2-4b07521ddf5a-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 70 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (40 dari 100), sementara Kenyamanan Bekerja sudah kuat di 70. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 16,7 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Manajemen jadi dimensi profil organisasi terendah menurut Anda (35 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan penyederhanaan satu laporan","instruksi":"Pilih laporan yang paling memakan waktu, lalu:","contoh":["Tandai bagian yang datanya sudah ada di tempat lain.","Hitung waktu yang habis tiap bulan.","Sampaikan ke bagian yang memintanya."],"tujuan":"Waktu administrasi yang kembali langsung terasa di jam mengajar."},{"judul":"Bantu bakukan satu alur yang sering berubah","instruksi":"Bersama unit Anda, sepakati:","contoh":["Format yang dipakai seterusnya.","Tenggat yang realistis.","Siapa yang menjawab kalau ada pertanyaan."],"tujuan":"Format yang stabil menghilangkan pekerjaan ulang yang tidak perlu."},{"judul":"Ajukan kalender kegiatan satu semester","instruksi":"Usulkan ke pimpinan:","contoh":["Kegiatan tetap yang sudah pasti.","Batas waktu penambahan kegiatan baru.","Cara mengumumkan perubahan."],"tujuan":"Kepastian jadwal adalah keluhan yang paling sering muncul dan paling mudah diperbaiki."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now())
