uhi","nilai":73.33,"kategori":"Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":60,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Sinergi Tim paling kuat Anda rasakan (65), sedangkan Karakter Lembaga paling rendah (50) dengan harapan 55.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":50,"kategori":"Sedang","harapan":55,"gap":5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"management","label":"Manajemen","nilai":60,"kategori":"Tinggi","harapan":55,"gap":-5},{"kode":"sinergi","label":"Sinergi Tim","nilai":65,"kategori":"Tinggi","harapan":65,"gap":0},{"kode":"fokus","label":"Fokus Strategis","nilai":55,"kategori":"Sedang","harapan":60,"gap":5},{"kode":"performance","label":"Kinerja/Performa","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5}]},"bagian_cermin":"\"Sesama guru saling menutup kalau ada yang berhalangan hadir.\" \"Menghadapi keluhan orang tua murid sendirian tanpa panduan yang jelas.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di Tata Usaha & Kantor Yayasan, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu keterampilan apa yang ingin Anda kuasai tiga bulan ke depan, dan kapan waktunya Anda sisihkan?","jawaban_survey":{"betah":"Sesama guru saling menutup kalau ada yang berhalangan hadir.","hal_menguras_energi":"Menghadapi keluhan orang tua murid sendirian tanpa panduan yang jelas.","yang_ingin_disampaikan":"Mohon kejelasan soal jenjang karier dan penghargaan kerja.","yang_ingin_diubah":"Pelatihan dibuka untuk semua, bukan bergiliran orang yang sama.","gambaran_lembaga":"tempat menitipkan harapan orang tua murid"},"rencana_aksi":[{"id":"db7f0d6a-9ad2-44ff-89dd-379c2c2875c8-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 28,8 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"db7f0d6a-9ad2-44ff-89dd-379c2c2875c8-aksi-2","judul":"Pilih satu keterampilan untuk didalami tiga bulan ini.","alasan":"Pengembangan Diri jadi sisi terendah Anda. Menetapkan satu fokus membuat waktu belajar yang sempit tetap membekas. Angkanya sekarang 46,7 dari 100.","terkait":"Pengembangan Diri","jangka":"3 bulan","ikon":"📚"},{"id":"db7f0d6a-9ad2-44ff-89dd-379c2c2875c8-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 80 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Pengembangan Diri jadi sisi kesejahteraan terendah Anda (46,7 dari 100), sementara Kenyamanan Bekerja sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Pilih satu keterampilan, bukan banyak sekaligus","instruksi":"Tentukan satu hal untuk didalami tiga bulan ke depan:","contoh":["Satu metode mengajar tertentu.","Satu alat bantu ajar yang belum dikuasai.","Satu cara menilai yang lebih cepat."],"tujuan":"Fokus yang sempit lebih mungkin selesai daripada rencana besar tanpa waktu."},{"judul":"Sisihkan 30 menit belajar dalam sepekan","instruksi":"Blokir satu slot tetap di jadwal Anda:","contoh":["Hari dan jam yang sama tiap pekan.","Bahan yang sudah disiapkan sebelumnya.","Catatan singkat setelah selesai."],"tujuan":"Kesempatan belajar jarang datang sendiri, ia harus dijadwalkan."},{"judul":"Cari satu rekan sebagai teman belajar","instruksi":"Ajak satu orang yang minatnya dekat:","contoh":["Sepakati apa yang mau dipelajari bersama.","Tentukan kapan saling mengabari kemajuan.","Coba satu praktik di kelas masing-masing."],"tujuan":"Belajar berdua membuat komitmen lebih sulit ditinggalkan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 28,8 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Karakter Lembaga jadi dimensi profil organisasi terendah menurut Anda (50 dari 100, harapan 55). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Sampaikan nilai mana yang belum terasa","instruksi":"Lewat forum resmi yang ada, sampaikan:","contoh":["Nilai yang sering disebut lembaga.","Bentuk nyatanya yang belum terlihat di unit Anda.","Contoh kejadian yang bisa dipakai sebagai bahan."],"tujuan":"Nilai lembaga jadi nyata kalau jaraknya dengan keseharian ikut dibicarakan."},{"judul":"Usulkan cara mengenalkan nilai ke staf baru","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Apa yang Anda alami saat pertama masuk.","Informasi yang dulu tidak Anda dapat.","Bentuk pengenalan yang menurut Anda cukup."],"tujuan":"Karakter lembaga paling mudah dititipkan pada orang yang baru bergabung."},{"judul":"Dokumentasikan kebiasaan baik unit Anda","instruksi":"Catat dan bagikan:","contoh":["Kebiasaan yang sudah berjalan bertahun-tahun.","Alasan kebiasaan itu bertahan.","Cara unit lain bisa menirunya."],"tujuan":"Kebiasaan yang tertulis lebih tahan pergantian orang."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now())
