('YPS-FAMMI', 'd4b2eec8-eba2-407e-8830-e52f6e87e849', '2026-07', '{"meta":{"responden_id":"d4b2eec8-eba2-407e-8830-e52f6e87e849","nama_responden":"Galih Mahendra","peran_kerja":"Pimpinan Unit","unit":"Tata Usaha & Kantor Yayasan","jenjang":"Non-Jenjang (TU, Kantor Yayasan)","jenis_kelamin":"Laki-laki","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"keluarga besar yang saling menutupi kekurangan\"","sub_hook":"Profil budaya Anda paling condong ke Aturan, dengan jarak terbesar ke harapan ada di Inovasi."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di Tata Usaha & Kantor Yayasan adalah Aturan (50,3 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Inovasi: Anda mengharapkan porsinya lebih besar sekitar 33,3 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":42.48,"harapan":55.47},{"tipe":"Inovasi","saat_ini":48.88,"harapan":82.2},{"tipe":"Orientasi","saat_ini":50.51,"harapan":54.06},{"tipe":"Aturan","saat_ini":50.3,"harapan":46.41}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":12.99},{"label":"Inovasi","arah":"naik","nilai_gap":33.32},{"label":"Orientasi","arah":"naik","nilai_gap":3.55},{"label":"Aturan","arah":"turun","nilai_gap":-3.89}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 66 dari 100, kategori Tinggi. Kenyamanan Bekerja jadi sisi terkuat Anda (80), sementara Pengembangan Diri paling perlu dijaga (53,3).","indeks":66,"kategori":"Tinggi","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":60,"kategori":"Tinggi"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":53.33,"kategori":"Sedang"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":66.67,"kategori":"Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":70,"kategori":"Tinggi"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Manajemen paling kuat Anda rasakan (60), sedangkan Karakter Lembaga paling rendah (50) dengan harapan 65.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":50,"kategori":"Sedang","harapan":65,"gap":15},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":55,"kategori":"Sedang","harapan":65,"gap":10},{"kode":"management","label":"Manajemen","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"sinergi","label":"Sinergi Tim","nilai":55,"kategori":"Sedang","harapan":65,"gap":10},{"kode":"fokus","label":"Fokus Strategis","nilai":60,"kategori":"Tinggi","harapan":75,"gap":15},{"kode":"performance","label":"Kinerja/Performa","nilai":60,"kategori":"Tinggi","harapan":70,"gap":10}]},"bagian_cermin":"\"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.\" \"Rapat panjang yang berakhir tanpa keputusan.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Aturan jadi sisi budaya yang paling terasa di Tata Usaha & Kantor Yayasan, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Satu keterampilan apa yang ingin Anda kuasai tiga bulan ke depan, dan kapan waktunya Anda sisihkan?","jawaban_survey":{"betah":"Rekan satu jenjang gampang diajak diskusi kalau ada murid yang butuh perhatian khusus.","hal_menguras_energi":"Rapat panjang yang berakhir tanpa keputusan.","yang_ingin_disampaikan":"Saya berharap keputusan sekolah dijelaskan alasannya ke semua staf.","yang_ingin_diubah":"Pelatihan dibuka untuk semua, bukan bergiliran orang yang sama.","gambaran_lembaga":"keluarga besar yang saling menutupi kekurangan"},"rencana_aksi":[{"id":"d4b2eec8-eba2-407e-8830-e52f6e87e849-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 33,3 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"d4b2eec8-eba2-407e-8830-e52f6e87e849-aksi-2","judul":"Pilih satu keterampilan untuk didalami tiga bulan ini.","alasan":"Pengembangan Diri jadi sisi terendah Anda. Menetapkan satu fokus membuat waktu belajar yang sempit tetap membekas. Angkanya sekarang 53,3 dari 100.","terkait":"Pengembangan Diri","jangka":"3 bulan","ikon":"📚"},{"id":"d4b2eec8-eba2-407e-8830-e52f6e87e849-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 80 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Pengembangan Diri jadi sisi kesejahteraan terendah Anda (53,3 dari 100), sementara Kenyamanan Bekerja sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Pilih satu keterampilan, bukan banyak sekaligus","instruksi":"Tentukan satu hal untuk didalami tiga bulan ke depan:","contoh":["Satu metode mengajar tertentu.","Satu alat bantu ajar yang belum dikuasai.","Satu cara menilai yang lebih cepat."],"tujuan":"Fokus yang sempit lebih mungkin selesai daripada rencana besar tanpa waktu."},{"judul":"Sisihkan 30 menit belajar dalam sepekan","instruksi":"Blokir satu slot tetap di jadwal Anda:","contoh":["Hari dan jam yang sama tiap pekan.","Bahan yang sudah disiapkan sebelumnya.","Catatan singkat setelah selesai."],"tujuan":"Kesempatan belajar jarang datang sendiri, ia harus dijadwalkan."},{"judul":"Cari satu rekan sebagai teman belajar","instruksi":"Ajak satu orang yang minatnya dekat:","contoh":["Sepakati apa yang mau dipelajari bersama.","Tentukan kapan saling mengabari kemajuan.","Coba satu praktik di kelas masing-masing."],"tujuan":"Belajar berdua membuat komitmen lebih sulit ditinggalkan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 33,3 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Karakter Lembaga jadi dimensi profil organisasi terendah menurut Anda (50 dari 100, harapan 65). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Sampaikan nilai mana yang belum terasa","instruksi":"Lewat forum resmi yang ada, sampaikan:","contoh":["Nilai yang sering disebut lembaga.","Bentuk nyatanya yang belum terlihat di unit Anda.","Contoh kejadian yang bisa dipakai sebagai bahan."],"tujuan":"Nilai lembaga jadi nyata kalau jaraknya dengan keseharian ikut dibicarakan."},{"judul":"Usulkan cara mengenalkan nilai ke staf baru","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Apa yang Anda alami saat pertama masuk.","Informasi yang dulu tidak Anda dapat.","Bentuk pengenalan yang menurut Anda cukup."],"tujuan":"Karakter lembaga paling mudah dititipkan pada orang yang baru bergabung."},{"judul":"Dokumentasikan kebiasaan baik unit Anda","instruksi":"Catat dan bagikan:","contoh":["Kebiasaan yang sudah berjalan bertahun-tahun.","Alasan kebiasaan itu bertahan.","Cara unit lain bisa menirunya."],"tujuan":"Kebiasaan yang tertulis lebih tahan pergantian orang."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
('YPS-FAMMI', 'a8988fd8-e933-4c62-b267-3c7bf9833799', '2026-07', '{"meta":{"responden_id":"a8988fd8-e933-4c62-b267-3c7bf9833799","nama_responden":"Doni Hakim","peran_kerja":"Tenaga Kependidikan","unit":"Tata Usaha & Kantor Yayasan","jenjang":"Non-Jenjang (TU, Kantor Yayasan)","jenis_kelamin":"Laki-laki","organisasi_id":"YPS-FAMMI","periode_id":"2026-07","nama_lembaga":"Yayasan Pendidikan Sekolah Fammi","sumber":"excel"},"header":{"hook":"Anda melihat Yayasan Pendidikan Sekolah Fammi ini sebagai \"rumah kedua yang hangat\"","sub_hook":"Profil budaya Anda paling condong ke Kekeluargaan, dengan jarak terbesar ke harapan ada di Inovasi."},"bagian_budaya":{"narasi":"Budaya yang paling Anda rasakan di Tata Usaha & Kantor Yayasan adalah Kekeluargaan (58,6 dari 100). Jarak terbesar antara kondisi sekarang dan harapan Anda ada di Inovasi: Anda mengharapkan porsinya lebih besar sekitar 33,1 poin dari yang Anda rasakan sekarang.","chart_data":[{"tipe":"Kekeluargaan","saat_ini":58.57,"harapan":65.16},{"tipe":"Inovasi","saat_ini":53.11,"harapan":86.18},{"tipe":"Orientasi","saat_ini":50.51,"harapan":43.62},{"tipe":"Aturan","saat_ini":57.85,"harapan":50.3}],"tabel_gap":[{"label":"Kekeluargaan","arah":"naik","nilai_gap":6.59},{"label":"Inovasi","arah":"naik","nilai_gap":33.07},{"label":"Orientasi","arah":"turun","nilai_gap":-6.89},{"label":"Aturan","arah":"turun","nilai_gap":-7.55}]},"bagian_kesejahteraan":{"narasi":"Kondisi kesejahteraan Anda secara umum berada di angka 65 dari 100, kategori Tinggi. Kenyamanan Bekerja jadi sisi terkuat Anda (80), sementara Work-Life Balance paling perlu dijaga (50).","indeks":65,"kategori":"Tinggi","chart_data":[{"kode":"kepuasan_kepemimpinan","label":"Kepuasan pada Kepemimpinan","nilai":53.33,"kategori":"Sedang"},{"kode":"kenyamanan_bekerja","label":"Kenyamanan Bekerja","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"pengembangan_diri","label":"Pengembangan Diri","nilai":66.67,"kategori":"Tinggi"},{"kode":"ekspektasi","label":"Ekspektasi Terpenuhi","nilai":73.33,"kategori":"Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Fokus Strategis paling kuat Anda rasakan (70), sedangkan Sinergi Tim paling rendah (55) dengan harapan 65.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":60,"kategori":"Tinggi","harapan":70,"gap":10},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"management","label":"Manajemen","nilai":65,"kategori":"Tinggi","harapan":60,"gap":-5},{"kode":"sinergi","label":"Sinergi Tim","nilai":55,"kategori":"Sedang","harapan":65,"gap":10},{"kode":"fokus","label":"Fokus Strategis","nilai":70,"kategori":"Tinggi","harapan":80,"gap":10},{"kode":"performance","label":"Kinerja/Performa","nilai":70,"kategori":"Tinggi","harapan":70,"gap":0}]},"bagian_cermin":"\"Pimpinan unit mau mendengar kalau ada keluhan yang disampaikan langsung.\" \"Menunggu keputusan yang tidak jelas siapa yang berwenang.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di Tata Usaha & Kantor Yayasan, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Pimpinan unit mau mendengar kalau ada keluhan yang disampaikan langsung.","hal_menguras_energi":"Menunggu keputusan yang tidak jelas siapa yang berwenang.","yang_ingin_disampaikan":"Saya berharap keputusan sekolah dijelaskan alasannya ke semua staf.","yang_ingin_diubah":"Pembagian tugas tambahan lebih merata antarguru.","gambaran_lembaga":"rumah kedua yang hangat"},"rencana_aksi":[{"id":"a8988fd8-e933-4c62-b267-3c7bf9833799-aksi-1","judul":"Ajukan satu metode mengajar baru untuk diuji coba.","alasan":"Ruang mencoba hal baru jadi jarak terbesar antara kondisi sekarang dan harapan Anda. Satu ide konkret lebih menggerakkan daripada menunggu ruangnya dibuka lebih dulu. Selisihnya 33,1 poin.","terkait":"Inovasi","jangka":"Bulan ini","ikon":"💡"},{"id":"a8988fd8-e933-4c62-b267-3c7bf9833799-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 50 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"a8988fd8-e933-4c62-b267-3c7bf9833799-aksi-3","judul":"Ajak satu rekan baru masuk ke lingkaran kerja Anda.","alasan":"Kenyamanan Bekerja jadi sisi terkuat Anda. Kekuatan ini bernilai kalau ditularkan ke orang yang belum merasakannya. Angkanya 80 dari 100.","terkait":"Kenyamanan Bekerja","jangka":"3 bulan","ikon":"🫱"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (50 dari 100), sementara Kenyamanan Bekerja sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Inovasi terpaut 33,1 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Ajukan ide metode mengajar di forum jenjang","instruksi":"Pada pertemuan rutin berikutnya, sampaikan:","contoh":["Satu metode yang ingin dicoba dan alasannya.","Dukungan yang Anda butuhkan.","Rencana waktu uji cobanya."],"tujuan":"Ruang eksperimen lebih cepat terbuka lewat usulan konkret daripada lewat keluhan."},{"judul":"Ajak satu rekan mencoba bersama","instruksi":"Sebelum forum berikutnya, tanyakan ke satu rekan:","contoh":["Ide mengajar yang ingin dia coba.","Kendala yang selama ini menahannya.","Kesediaannya ikut menyampaikan."],"tujuan":"Dua suara lebih sulit diabaikan daripada satu."},{"judul":"Catat hasil percobaan Anda sendiri","instruksi":"Setelah mencoba, tuliskan:","contoh":["Apa yang berubah pada murid.","Kendala yang muncul.","Apa yang perlu diperbaiki kalau diulang."],"tujuan":"Catatan hasil membuat ide berikutnya lebih mudah disetujui."}]},{"locus":"system","mengapa_fokus":"Sinergi Tim jadi dimensi profil organisasi terendah menurut Anda (55 dari 100, harapan 65). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan satu pertemuan lintas jenjang","instruksi":"Sampaikan ke pimpinan unit:","contoh":["Topik yang dibutuhkan dua jenjang sekaligus.","Waktu yang paling mungkin untuk keduanya.","Hasil yang diharapkan dari pertemuan itu."],"tujuan":"Silo antarjenjang jarang hilang sendiri, ia perlu satu pertemuan pertama."},{"judul":"Bagikan bahan ajar Anda ke jenjang lain","instruksi":"Pilih satu bahan yang bisa dipakai ulang:","contoh":["Kirim ke rekan jenjang di atas atau di bawah.","Jelaskan konteks pemakaiannya.","Minta masukan balik."],"tujuan":"Kerja sama tumbuh lebih cepat lewat pertukaran yang nyata daripada lewat ajakan."},{"judul":"Usulkan satu proyek kecil bersama","instruksi":"Ajukan proyek yang butuh dua unit:","contoh":["Lingkupnya kecil dan selesai dalam satu bulan.","Tugas tiap unit jelas.","Ada hasil yang bisa dilihat murid."],"tujuan":"Keberhasilan kecil lintas unit membuka jalan untuk yang lebih besar."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
