tasi","label":"Ekspektasi Terpenuhi","nilai":80,"kategori":"Sangat Tinggi"},{"kode":"work_life_balance","label":"Work-Life Balance","nilai":50,"kategori":"Sedang"}]},"bagian_profil_organisasi":{"narasi":"Dari enam dimensi profil organisasi, Fokus Strategis paling kuat Anda rasakan (85), sedangkan Manajemen paling rendah (60) dengan harapan 60.","chart_data":[{"kode":"karakter_lembaga","label":"Karakter Lembaga","nilai":70,"kategori":"Tinggi","harapan":65,"gap":-5},{"kode":"kepemimpinan","label":"Kepemimpinan","nilai":75,"kategori":"Sangat Tinggi","harapan":70,"gap":-5},{"kode":"management","label":"Manajemen","nilai":60,"kategori":"Tinggi","harapan":60,"gap":0},{"kode":"sinergi","label":"Sinergi Tim","nilai":60,"kategori":"Tinggi","harapan":65,"gap":5},{"kode":"fokus","label":"Fokus Strategis","nilai":85,"kategori":"Sangat Tinggi","harapan":60,"gap":-25},{"kode":"performance","label":"Kinerja/Performa","nilai":80,"kategori":"Sangat Tinggi","harapan":60,"gap":-20}]},"bagian_cermin":"\"Jarak dari rumah dekat dan jam kerjanya jelas.\" \"Pekerjaan yang terbawa sampai rumah hampir setiap malam.\" Dua kalimat itu Anda tulis sendiri bulan ini. Keduanya menjelaskan kenapa Kekeluargaan jadi sisi budaya yang paling terasa di Tata Usaha & Kantor Yayasan, sekaligus di mana energinya paling banyak terpakai.","bagian_refleksi":"Jam berapa Anda ingin benar-benar berhenti bekerja hari ini, dan apa yang perlu disiapkan supaya itu terjadi?","jawaban_survey":{"betah":"Jarak dari rumah dekat dan jam kerjanya jelas.","hal_menguras_energi":"Pekerjaan yang terbawa sampai rumah hampir setiap malam.","yang_ingin_disampaikan":"Saya berharap keputusan sekolah dijelaskan alasannya ke semua staf.","yang_ingin_diubah":"Evaluasi program dijalankan rutin, bukan cuma saat ada masalah.","gambaran_lembaga":"tempat yang aman, cuma kurang ruang mencoba"},"rencana_aksi":[{"id":"2be70152-28c4-4466-8a3c-13b1a29c7654-aksi-1","judul":"Coba satu keputusan kecil tanpa menunggu prosedur baru.","alasan":"Aturan terasa lebih mengikat dari yang Anda butuhkan. Mengambil satu keputusan di wilayah Anda sendiri membuktikan ruang gerak itu sebenarnya ada. Selisihnya 30,4 poin.","terkait":"Aturan","jangka":"Minggu ini","ikon":"🚪"},{"id":"2be70152-28c4-4466-8a3c-13b1a29c7654-aksi-2","judul":"Tetapkan satu jam yang tidak diganggu pekerjaan.","alasan":"Work-Life Balance jadi sisi terendah Anda. Satu jam yang dijaga konsisten lebih realistis daripada menunggu beban kerja berkurang sendiri. Angkanya sekarang 50 dari 100.","terkait":"Work-Life Balance","jangka":"Minggu ini","ikon":"🕰️"},{"id":"2be70152-28c4-4466-8a3c-13b1a29c7654-aksi-3","judul":"Jadi penyambung suara rekan ke pimpinan.","alasan":"Kepuasan Anda pada kepemimpinan jadi yang tertinggi. Kepercayaan itu paling berguna kalau dipakai membawa masukan rekan yang belum berani menyampaikan. Angkanya 80 dari 100.","terkait":"Kepuasan pada Kepemimpinan","jangka":"3 bulan","ikon":"🔗"}],"lingkar_kontribusi":[{"locus":"control","mengapa_fokus":"Work-Life Balance jadi sisi kesejahteraan terendah Anda (50 dari 100), sementara Kepuasan pada Kepemimpinan sudah kuat di 80. Tiga langkah di bawah ini seluruhnya bisa Anda mulai sendiri.","langkah":[{"judul":"Tetapkan jam berhenti kerja setiap hari","instruksi":"Pilih satu jam sebagai batas, lalu:","contoh":["Tutup pekerjaan administrasi di jam itu.","Simpan berkas yang belum selesai untuk besok.","Beri tahu rekan terdekat soal batas itu."],"tujuan":"Batas yang diumumkan lebih mudah dijaga daripada niat yang disimpan sendiri."},{"judul":"Kelompokkan pekerjaan koreksi di satu waktu","instruksi":"Alih-alih dicicil setiap malam:","contoh":["Tentukan dua slot koreksi dalam sepekan.","Siapkan semua bahan sebelum mulai.","Kerjakan di sekolah, bukan di rumah."],"tujuan":"Pekerjaan yang dikelompokkan selesai lebih cepat dan tidak menempel sepanjang minggu."},{"judul":"Jaga satu hari tanpa pekerjaan sekolah","instruksi":"Pilih satu hari dalam sepekan, lalu:","contoh":["Jangan buka berkas pekerjaan hari itu.","Beri tahu rekan sejak awal pekan.","Isi dengan hal yang benar-benar memulihkan."],"tujuan":"Pemulihan butuh jeda yang utuh, bukan sisa waktu di sela pekerjaan."}]},{"locus":"influence","mengapa_fokus":"Harapan Anda pada Aturan terpaut 30,4 poin dari kondisi sekarang, jarak terbesar di antara empat tipe budaya. Ini wilayah yang bergerak lewat percakapan dengan rekan dan koordinator, bukan sendirian.","langkah":[{"judul":"Usulkan satu prosedur yang perlu disederhanakan","instruksi":"Pilih satu prosedur yang paling sering menghambat, lalu:","contoh":["Tuliskan langkah yang sebenarnya tidak perlu.","Perkirakan waktu yang bisa dihemat.","Sampaikan ke koordinator unit."],"tujuan":"Aturan yang dirapikan mengembalikan waktu ke pekerjaan utama."},{"judul":"Bantu perjelas satu alur kerja yang membingungkan","instruksi":"Bersama satu rekan, buat:","contoh":["Daftar langkah dari awal sampai selesai.","Nama orang yang bertanggung jawab tiap langkah.","Contoh berkas yang benar."],"tujuan":"Kebingungan berulang biasanya bukan soal orangnya, tapi alurnya yang tidak pernah dituliskan."},{"judul":"Sampaikan aturan yang sudah tidak relevan","instruksi":"Kalau ada aturan yang tidak lagi cocok:","contoh":["Ceritakan kapan terakhir itu berguna.","Jelaskan hambatannya sekarang.","Usulkan penggantinya, bukan cuma penghapusannya."],"tujuan":"Usulan yang membawa pengganti lebih mungkin dipertimbangkan."}]},{"locus":"system","mengapa_fokus":"Manajemen jadi dimensi profil organisasi terendah menurut Anda (60 dari 100, harapan 60). Perubahan di wilayah ini butuh keputusan lembaga, yang bisa Anda lakukan adalah memasok bahannya.","langkah":[{"judul":"Usulkan penyederhanaan satu laporan","instruksi":"Pilih laporan yang paling memakan waktu, lalu:","contoh":["Tandai bagian yang datanya sudah ada di tempat lain.","Hitung waktu yang habis tiap bulan.","Sampaikan ke bagian yang memintanya."],"tujuan":"Waktu administrasi yang kembali langsung terasa di jam mengajar."},{"judul":"Bantu bakukan satu alur yang sering berubah","instruksi":"Bersama unit Anda, sepakati:","contoh":["Format yang dipakai seterusnya.","Tenggat yang realistis.","Siapa yang menjawab kalau ada pertanyaan."],"tujuan":"Format yang stabil menghilangkan pekerjaan ulang yang tidak perlu."},{"judul":"Ajukan kalender kegiatan satu semester","instruksi":"Usulkan ke pimpinan:","contoh":["Kegiatan tetap yang sudah pasti.","Batas waktu penambahan kegiatan baru.","Cara mengumumkan perubahan."],"tujuan":"Kepastian jadwal adalah keluhan yang paling sering muncul dan paling mudah diperbaiki."}]}],"footer":{"disclaimer":"Laporan ini adalah hasil pengolahan jawaban asesmen Anda dan bersifat rahasia. Gunakan sebagai bahan refleksi pribadi, bukan alat penilaian kinerja formal."}}'::jsonb, 'disetujui', now()),
